FENCE=head/.claude/hooks/safety/block-destructive-bash.sh; ERR=/tmp/ferr; : > $ERR
awk -v errs="$ERR" '
  function note(s) { print s >> errs }
  /^[[:space:]]*#[[:space:]]*@guard[[:space:]]+fence:/ {
    s = $0; sub(/^[[:space:]]*#[[:space:]]*@guard[[:space:]]+fence:/, "", s); sub(/[[:space:]]+$/, "", s)
    if (s !~ /^[A-Za-z0-9._-]+$/) { note("fence marker at line " NR " has an invalid id"); next }
    nm++; mline[nm] = NR; mid[nm] = s; next
  }
  /^[[:space:]]*#/ { next }
  {
    line = $0
    if (line ~ /emit_block[[:space:]]*\(\)/) next
    while (match(line, /emit_block[[:space:]]+[^[:space:]]+/)) {
      tok = substr(line, RSTART, RLENGTH); line = substr(line, RSTART + RLENGTH)
      sub(/^emit_block[[:space:]]+/, "", tok)
      if (tok ~ /^"[A-Za-z0-9._-]+"$/) { gsub(/"/, "", tok); ns++; sline[ns] = NR; sid[ns] = tok }
      else note("fence emit_block call at line " NR " has a non-literal pattern id")
    }
    line = $0
    while (match(line, /pattern_id(: |=)"[A-Za-z0-9._-]+"/)) {
      tok = substr(line, RSTART, RLENGTH); line = substr(line, RSTART + RLENGTH)
      sub(/^pattern_id(: |=)"/, "", tok); sub(/"$/, "", tok)
      ns++; sline[ns] = NR; sid[ns] = tok
    }
  }
  END {
    for (i = 1; i <= ns; i++) { ok = 0
      for (j = 1; j <= nm; j++) if (mid[j] == sid[i] && mline[j] < sline[i] && sline[i] - mline[j] <= 8) ok = 1
      if (!ok) note("fence site " sid[i] " at line " sline[i] " has no marker") }
    for (j = 1; j <= nm; j++) { ok = 0
      for (i = 1; i <= ns; i++) if (mid[j] == sid[i] && mline[j] < sline[i] && sline[i] - mline[j] <= 8) ok = 1
      if (!ok) note("fence marker " mid[j] " at line " mline[j] " has no site")
      print mid[j] }
  }' "$FENCE" | sort -u > /tmp/fence.ids
echo "ERRORS:"; cat $ERR; echo "IDS:"; cat /tmp/fence.ids | tr '\n' ' '; echo
echo "--- origin map fence ids"; yq -r '.guards[] | select(.kind=="fence") | .id' head/.claude/data/guard-origins.yaml | sed 's/^fence://' | sort -u > /tmp/map.fence
diff <(cat /tmp/fence.ids) /tmp/map.fence && echo "fence ids match"
echo "--- validator markers"; grep -n '@guard validator:' head/.claude/scripts/validate-artifact.sh | sed 's/.*validator://' | sort -u > /tmp/val.ids; cat /tmp/val.ids | tr '\n' ' '; echo
yq -r '.guards[] | select(.kind=="validator") | .id' head/.claude/data/guard-origins.yaml | sed 's/^validator://' | sort -u > /tmp/map.val
diff /tmp/val.ids /tmp/map.val && echo "validator ids match"
echo "--- gates/policies"; yq -r '.guards[] | select(.kind=="gate" or .kind=="policy") | .id + " " + .script' head/.claude/data/guard-origins.yaml
echo "--- floor"; yq -r '.guards[] | select(.floor==true) | .id' head/.claude/data/guard-origins.yaml | sort > /tmp/map.floor; yq -r '.floor_guards[]' head/.claude/data/floor.yaml | sort | diff - /tmp/map.floor && echo "floor matches"

